from pathlib import Path
import hashlib,json,statistics,time
B=Path(__file__).resolve().parent;O=B/'r98-two-step';R=O/'run'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
f=read(O/'FREEZE.json');s=read(R/'SUMMARY.json')
assert all(sha(O/n)==h for n,h in f['source_sha256'].items())
cases=[]
for row in s['rows']:
 c=R/row['case'];r=read(c/'RESULT.json');e=read(c/'work/EXECUTION.json');d=read(c/'work/DELIVERY.json')
 assert row['valid'] and r['valid'] and r['jobs']==128 and r['file_checks']==6144
 assert d['status']=='VALID' and d['accepted']==d['requested']==128 and d['files']==6144
 assert {x['index'] for x in e['results']}==set(range(128))
 assert len({x['pid'] for x in e['results']})==row['workers']
 assert all(x['exit_code']==0 and x['item_acceptance'] for x in e['results'])
 lanes=[]
 for m in e['lane_metrics']:
  ids=[x['index'] for x in m['results']]
  assert len(ids)==128//row['workers'] and ids==list(range(min(ids),max(ids)+1))
  lanes.append({'pid':m['pid'],'count':len(ids),'indices':ids,'wall_s':m['stream_wall_s'],'cpu_s':m['job_cpu_s']})
 cases.append({**row,'lanes':lanes,'match_sum_s':sum(x['match_s'] for x in e['results']),'job_wall_sum_s':sum(x['end']-x['start'] for x in e['results']),'worker_cpu_s':sum(x['cpu_s'] for x in e['results']),'worker_span_s':max(x['end'] for x in e['results'])-min(x['start'] for x in e['results']),'receipt_sha256':sha(c/'RESULT.json')})
groups={}
for key in ['production_s','production_with_fixture_s','total_s','total_with_fixture_s']:
 g={}
 for w in [1,4]:
  vals=[r[key] for r in cases if r['workers']==w]
  g[str(w)]={'mean_s':statistics.mean(vals),'range_s':[min(vals),max(vals)]}
 g['speedup_mean']=g['1']['mean_s']/g['4']['mean_s']
 g['speedup_pairs']=[cases[0][key]/cases[1][key],cases[3][key]/cases[2][key]]
 groups[key]=g
out={'task_id':f['task_id'],'created_epoch':time.time(),'quality':'VALID','accepted':512,'file_checks':24576,'freeze':f,'freeze_sha256':sha(O/'FREEZE.json'),'summary':s,'cases':cases,'groups':groups,'source_checks_unchanged':True,'physical_limit':'NOT_ESTABLISHED','stable_speedup':'TWO_PAIRS_ONLY_NOT_CERTIFIED','retention':'all four cases retained, no fastest-sample reruns','audit_scope':'original full external independent input/ZIP byte+CRC/manifest/receipt/source/request QA preserved under total_s; production per-item QA binding remains, no batch input or ZIP rescan','source_snapshot':{n:(B/n).read_text(encoding='utf-8') for n in ['r98_prepare.py','r98_finalize.py','r98-two-step/benchmark.py','r98-two-step/snapshot/scripts/archive_stream_worker.py','r98-two-step/snapshot/scripts/accept_archive_item.py','r98-two-step/snapshot/scripts/deliver_archive_batch.py','r98-two-step/launch_pi.py']}}
(O/'R98-Evidence.json').write_text(json.dumps(out,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in out.items() if k not in ['source_snapshot','freeze','summary','cases']}),flush=True)

